        subsidiaryList.map((subsidiary: NetSuiteSubsidiary) => ({
            text: subsidiary.name,
            keyForList: subsidiary.internalID,
            isSelected: subsidiary.name === currentSubsidiaryName,
            value: subsidiary.name,
